import json, itertools, numpy as np
from scipy.stats import pearsonr
from pathlib import Path

mi_data = json.load(open('artifacts/results/plan001/mi_matrix/mi_matrix_15models.json'))
MODELS = mi_data['models']
N = len(MODELS)
mi_matrices = {ds: np.array(mi_data['mi_matrix'][ds]) for ds in ['mmlu','arc_challenge']}
DATASETS = ['mmlu','arc_challenge']
ATTACKS = ['prompt_injection','sycophancy','score_manipulation','verbosity_bias','position_bias','authority_bias']
LOCAL_SET = {'qwen2.5-72b','llama3.1-70b','mistral-large','qwen2.5-32b','qwen2.5-14b','llama3.1-8b'}
CKPT_FILES = ['artifacts/results/_taxonomy_checkpoint.json','artifacts/results/_step2v3_checkpoint.json']
SCORES_DIR = Path('artifacts/results/plan001/individual_scores')

def _is_valid(s):
    if s.get('error') or s.get('format_error'): return False
    return s.get('winner') in ('A','B','tie')
def _invert(scores):
    swap = {'A':'B','B':'A','tie':'tie'}
    return [{**s,'winner':swap.get(s.get('winner','tie'),'tie')} for s in scores]

clean = {ds:{} for ds in DATASETS}
attacked = {ds:{a:{} for a in ATTACKS} for ds in DATASETS}
pairs = {}
for ckpt_path in CKPT_FILES:
    p = Path(ckpt_path)
    if not p.exists(): continue
    data = json.load(open(p))
    if 'pairs' in data and not pairs:
        for ds in DATASETS:
            if ds in data['pairs']: pairs[ds] = data['pairs'][ds][:300]
    for ds in DATASETS:
        for mid, scores in data.get('clean_scores',{}).get(ds,{}).items():
            if mid not in clean[ds]: clean[ds][mid] = scores
        for atk in ATTACKS:
            for mid, scores in data.get('attacked_scores',{}).get(ds,{}).get(atk,{}).items():
                if mid not in attacked[ds][atk]:
                    if atk == 'position_bias': scores = _invert(scores)
                    attacked[ds][atk][mid] = scores
for mid in MODELS:
    if mid in LOCAL_SET: continue
    for ds in DATASETS:
        fp = SCORES_DIR / f'{mid}__{ds}__clean.json'
        if fp.exists() and mid not in clean[ds]:
            clean[ds][mid] = json.load(open(fp)).get('scores',[])
        for atk in ATTACKS:
            fp = SCORES_DIR / f'{mid}__{ds}__{atk}.json'
            if fp.exists() and mid not in attacked[ds][atk]:
                scores = json.load(open(fp)).get('scores',[])
                if atk == 'position_bias': scores = _invert(scores)
                attacked[ds][atk][mid] = scores

def individual_asr(mid, ds, atk):
    if mid not in clean[ds] or mid not in attacked[ds][atk]: return None
    ps = pairs[ds]; c = clean[ds][mid]; a = attacked[ds][atk][mid]
    n = min(len(ps),len(c),len(a))
    if n==0: return None
    nc=nf=0
    for i in range(n):
        if not _is_valid(c[i]) or not _is_valid(a[i]): continue
        gt = ps[i]['ground_truth_winner']
        if c[i]['winner']==gt:
            nc+=1
            if a[i]['winner']!=gt: nf+=1
    return nf/nc if nc>0 else 0.0

ind_asr = {}
for ds in DATASETS:
    for atk in ATTACKS:
        for mid in MODELS:
            a = individual_asr(mid, ds, atk)
            if a is not None: ind_asr[(ds, atk, mid)] = a

def mi_keff(mi_mat, indices):
    K = len(indices)
    if K<=1: return 1.0
    total = 0.0
    for i in indices:
        term = 1.0
        for j in indices:
            if i!=j: term += np.exp(-2*mi_mat[i,j])
        total += term
    return total / K

eps = 1e-6
combos = list(itertools.combinations(range(N), 3))

# Compute per-panel K_eff (per-ds) and per-condition eta_max
keff_mmlu = np.array([mi_keff(mi_matrices['mmlu'], list(c)) for c in combos])
keff_arc = np.array([mi_keff(mi_matrices['arc_challenge'], list(c)) for c in combos])

print('Per-condition log-space VIF (K=3, 455 panels):')
all_vif = []
for ds in DATASETS:
    ke = keff_mmlu if ds == 'mmlu' else keff_arc
    log_ke = np.log(ke)
    for atk in ATTACKS:
        etas = np.array([max(ind_asr.get((ds, atk, MODELS[i]), 0.0) for i in c) for c in combos])
        log_eta = np.log(etas + eps)
        r, _ = pearsonr(log_ke, log_eta)
        vif = 1/(1-r**2) if abs(r) < 1 else float('inf')
        all_vif.append(vif)
        print(f'  {ds} x {atk}: r_log={r:.4f}, VIF={vif:.2f}')

print(f'Mean VIF: {np.mean(all_vif):.2f}')
print(f'Median VIF: {np.median(all_vif):.2f}')
print(f'Range: {np.min(all_vif):.2f} -- {np.max(all_vif):.2f}')
" 2>&1

